let lang = "en";

// pickLanguage: "auto" follows the language of Windows (the web view gets
// it from there).
function pickLanguage(setting, browserLanguage) {
  if (setting === "en" || setting === "de") return setting;
  return String(browserLanguage || "").toLowerCase().startsWith("de") ? "de" : "en";
}

function setLanguage(l) {
  lang = texts[l] ? l : "en";
}

// t returns the text for key, with {name} filled from vars. A missing key
// shows the key itself: visible in a check, never an empty label.
function t(key, vars) {
  let s = (texts[lang] && texts[lang][key]) || texts.en[key] || key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) s = s.split("{" + k + "}").join(String(v));
  }
  return s;
}

globalThis.vcTexts = texts;
globalThis.vcT = t;
globalThis.vcSetLanguage = setLanguage;
globalThis.vcPickLanguage = pickLanguage;
